import { agentColorFor } from "./agentColor";
import { palettes, semantic, type Palette, type PaletteSide } from "./palettes";
import { getLocale, tr } from "../i18n/index.ts";

/**
 * Window skin = a set of --ui-* variables written to <html> at runtime by useSkin; skins.css only
 * maps UI utility and component class names to these variables. The ten sets in the theme library
 * (five palettes × dark/light) are generated by palettes.ts; the "More" group holds extra skins
 * not present in the design draft.
 */
export type SkinMode = "dark" | "light";

export interface Skin {
  id: string;
  name: string;
  /** Grouping: Theme library / More */
  group: string;
  mode: SkinMode;
  description: string;
  vars: Record<string, string>;
}

const mix = (a: string, b: string, pa: number) => `color-mix(in oklab, ${a} ${pa}%, ${b})`;

/** Relative luminance (WCAG) of #rrggbb, used solely to pick black or white text for clips */
function relLuminance(hex: string): number {
  const m = /^#?([\da-f]{6})$/i.exec(hex.trim());
  if (!m) return 0.5;
  const n = parseInt(m[1], 16);
  const ch = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => {
    const s = v / 255;
    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * ch[0] + 0.7152 * ch[1] + 0.0722 * ch[2];
}

/** Blends a toward b by pa% in sRGB, returning #rrggbb */
function mixHex(a: string, b: string, pa: number): string {
  const rgb = (h: string) => {
    const n = parseInt(/^#?([\da-f]{6})$/i.exec(h.trim())![1], 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  };
  const [ra, ga, ba] = rgb(a);
  const [rb, gb, bb] = rgb(b);
  const k = pa / 100;
  const ch = [ra * k + rb * (1 - k), ga * k + gb * (1 - k), ba * k + bb * (1 - k)];
  return "#" + ch.map((v) => Math.round(v).toString(16).padStart(2, "0")).join("");
}

const contrast = (l1: number, l2: number) =>
  (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);

/**
 * What color to use for text on clips.
 *
 * Cannot apply a one-size-fits-all rule based on dark/light skins: track colors in dark skins are
 * bright (black text is clearer), while light skins mostly use dark tones (white text is clearer),
 * but light Amber #A5762A is on the lighter side, requiring black text instead. Calculate color by
 * color.
 *
 * Clip background is a gradient (top brightened by 8%, bottom darkened by 12%), so contrast differs
 * at the two ends; evaluation uses whichever end is worse. Try tinted dark text first (looks better),
 * falling back all the way to pure black / pure white if it fails 4.5:1.
 */
function trackInk(track: string): string {
  const ends = [mixHex(track, "#ffffff", 92), mixHex(track, "#000000", 88)].map(relLuminance);
  const worst = (ink: string) => {
    const li = relLuminance(ink);
    return Math.min(...ends.map((le) => contrast(le, li)));
  };
  const toward = worst("#000000") >= worst("#ffffff") ? "#000000" : "#ffffff";
  for (const amount of [22, 14, 7]) {
    const candidate = mixHex(track, toward, amount);
    if (worst(candidate) >= 4.5) return candidate;
  }
  return toward;
}

function sideToVars(side: PaletteSide, mode: SkinMode): Record<string, string> {
  const [l0, l1, l2, l3, l4] = side.surfaces;
  const dark = mode === "dark";
  const sem = semantic[mode];
  // Use themes with values explicitly specified in the design draft (Steel Blue · Dark) directly;
  // derive the rest from surfaces as usual
  const borderStrong = side.borderStrong ?? side.border ?? mix(l4, side.fg, 84);
  const border = side.hairline ?? (dark ? mix(l3, l4, 45) : mix(borderStrong, "#ffffff", 55));
  return {
    "ui-bg": l0,
    "ui-bg-2": l1,
    "ui-panel": l2,
    "ui-panel-2": l3,
    "ui-float": l4,
    "ui-border": border,
    "ui-border-strong": borderStrong,
    "ui-fg": side.fg,
    "ui-fg-muted": side.fgMuted,
    "ui-fg-faint": side.fgFaint ?? mix(side.fgMuted, l1, 62),
    "ui-accent": side.accent,
    // Which direction to blend on hover depends on the accent color's own lightness. It previously
    // always blended toward white, assuming that "accent colors in dark themes always have medium
    // saturation"; with light accents (e.g. light cyan), blending toward white yields almost no
    // visible change, making button hover feel unresponsive. Light accents blend toward black instead.
    "ui-accent-hover": relLuminance(side.accent) > 0.55
      ? mix(side.accent, "#000000", 88)
      : mix(side.accent, "#ffffff", dark ? 82 : 78),
    "ui-accent-press": relLuminance(side.accent) > 0.55
      ? mix(side.accent, "#000000", 76)
      : mix(side.accent, "#000000", dark ? 78 : 74),
    // Brand gradient: same as the start page "Start creating" banner, transitioning from accent color
    // to purple.
    // Endpoint is almost pure purple (only 10% accent color mixed in): mixing too much makes both ends
    // bluish, hiding the gradient on small elements like buttons and pills.
    // Angle 100°: nearly horizontal, spreads along the button's long edge, keeping contrast even on
    // short, wide controls.
    // The first 30% retains the accent color; purple appears only at the tail end.
    // Only used for primary action buttons (primary button, export, send, start page banner); selected
    // state, indicator bar, dots, progress, user bubbles, and text stroke still use solid --ui-accent,
    // as applying gradients everywhere makes the UI overly purple.
    // Written as a var() expression rather than a computed color: when the user changes the accent
    // color in skin editing, the gradient updates accordingly.
    "ui-accent-2": "color-mix(in srgb, var(--ui-accent) 10%, #7b5cff)",
    "ui-accent-grad": "linear-gradient(100deg, var(--ui-accent) 30%, var(--ui-accent-2))",
    "ui-accent-grad-hover": "linear-gradient(100deg, var(--ui-accent-hover) 30%, color-mix(in srgb, var(--ui-accent-hover) 10%, #7b5cff))",
    "ui-accent-grad-press": "linear-gradient(100deg, var(--ui-accent-press) 30%, color-mix(in srgb, var(--ui-accent-press) 10%, #7b5cff))",
    "ui-accent-fg": dark ? l0 : "#ffffff",
    "ui-accent-soft": dark ? mix(side.accent, l1, 24) : mix(side.accent, "#ffffff", 14),
    "ui-danger": sem.danger,
    "ui-warn": sem.warn,
    "ui-success": sem.success,
    "ui-info": side.accent,
    // Agent exclusive color: yellow with the same lightness and chroma as the accent color
    // (agentColor.ts), used for Agent avatars on the rail
    "ui-agent": agentColorFor(side.accent),
    "ui-track-video": side.tracks.video,
    "ui-track-audio": side.tracks.audio,
    "ui-track-image": side.tracks.image,
    "ui-track-text": side.tracks.text,
    "ui-track-fx": side.tracks.fx,
    "ui-track-transition": side.tracks.transition,
    "ui-track-sticker": side.tracks.sticker,
    "ui-track-ink-video": trackInk(side.tracks.video),
    "ui-track-ink-audio": trackInk(side.tracks.audio),
    "ui-track-ink-image": trackInk(side.tracks.image),
    "ui-track-ink-text": trackInk(side.tracks.text),
    "ui-track-ink-fx": trackInk(side.tracks.fx),
    "ui-track-ink-transition": trackInk(side.tracks.transition),
    "ui-track-ink-sticker": trackInk(side.tracks.sticker),
    "ui-radius-sm": "4px",
    "ui-radius": "6px",
    "ui-radius-lg": "8px",
    "ui-radius-xl": "10px",
    "ui-gap": "8px",
    "ui-rail-w": getLocale() === "ja" ? "88px" : getLocale() === "en" ? "80px" : "64px",
    "ui-rail-label-size": getLocale() === "ja" ? "10px" : "11px",
    "pc-cube-s": "64px",
    "pc-cube-gap": "8px",
    "ui-focus-ring": "0 0 0 2px var(--ui-accent)",
    "ui-shadow": dark ? "0 6px 18px rgba(0, 0, 0, 0.45)" : "0 8px 24px rgba(20, 22, 24, 0.14)",
    "ui-glow": `0 0 10px ${mix(side.accent, "transparent", 45)}`,
    "ui-font": '"Segoe UI Variable Text", "Segoe UI", "Microsoft YaHei UI", "PingFang SC", system-ui, sans-serif',
    "ui-font-mono": "ui-monospace, SFMono-Regular, monospace",
    "ui-backdrop": dark ? mix(l0, "transparent", 72) : "rgba(20, 22, 24, 0.35)",
    "ui-scroll-thumb": borderStrong,
    "ui-scroll-thumb-hover": side.fgMuted,
  };
}

function paletteSkins(p: Palette): Skin[] {
  return [
    { id: `${p.id}-dark`, name: tr("{0} · Dark ({1})", p.name, p.en), group: tr("Theme library"), mode: "dark", description: p.blurb, vars: sideToVars(p.dark, "dark") },
    { id: `${p.id}-light`, name: tr("{0} · Light ({1})", p.name, p.en), group: tr("Theme library"), mode: "light", description: p.blurb, vars: sideToVars(p.light, "light") },
  ];
}

/**
 * Extra skins: provide base variables only; the rest (hover layers, accent states, semantic
 * colors, track colors) fall back to Steel Blue Dark
 */
function extra(id: string, name: string, description: string, vars: Record<string, string>): Skin {
  const steelPalette = palettes.find((p) => p.id === "steel") ?? palettes[0];
  const base = sideToVars(steelPalette.dark, "dark");
  // Agent color is recalculated from this skin's own accent color; cannot reuse steel blue's
  const agent = vars["ui-agent"] ?? agentColorFor(vars["ui-accent"] ?? base["ui-accent"]);
  return { id, name, group: tr("More"), mode: "dark", description, vars: { ...base, ...vars, "ui-agent": agent } };
}

